				}else{
					type += "N";
				}
				tile=layerObj[type];
			}
		}else{
			tile = mapObj["tile"];
		}
		var tileArr =tile.split(",");
		
		var rsList = new Array();
		var rsBaseList = new Array();
		
		if($(".subj ul li em.typeA").hasClass("on")||$(".subj ul li em.typeB").hasClass("on")||$(".subj ul li em.typeC").hasClass("on")){
			$("ul.bum").show();
			$("ul.ji").hide();
			for(var i=0 ; i<tileArr.length ; i++){
				var params = {
						version: version,
						mbr: coordValue,
						tiles : tileArr[i],
						levelId : levelIdValue,
						accuracy : accuracyValue
				};
				$.getJSON(jsonurl, params, function(data, status) {
					$.each(data, function(i, item) {
						for(var k=0; k<item.length; k++){
							if(item[k].name!="CB"){
								rsList[rsList.length]=item[k];
								rsBaseList[rsBaseList.length]=item[k];
							}
						}
					});
					lcstSpaceLayer=rsBaseList;
					if(!$.fn.isEmptyGis(lcstSpace)){
						var lcstSpaceObj={
							"name":lcstSpace.split("_")[0].replace("type",""),
							"code":[lcstSpace.split("_")[1]]
						}
						rsList[rsList.length]=lcstSpaceObj;
					}
					$.fn.setLeftHtml(rsList);
				});
			}
		}else{
			$("ul.bum").hide();
			$("div.scr p").hide();
			
			
			$("ul.ji").show();
			$("p.tit").hide();
			$("p.tit2").hide();
		}
		
		if($(".subj ul li em.type0").hasClass("on")){
			
		}else{
			
		}
		
		
	}
}

functions.setLeftHtml:
$.fn.setLeftHtml = function(rsList){
	var height = $('.scroll-scrolly_visible').scrollTop();
	var html="";
	$("div.scr p").hide();
	$("div.scr ul.bum li").hide();
	var showList="";
	if(rsList!=null){
		$("p.tit").show();
		for(var i=0 ; i<rsList.length ; i++){
			var seName= rsList[i].name;
			var firName= seName.substring(0,1);
			$("div.scr p.type"+firName).show();
			$("div.scr ul li.type"+seName).show();
			var seViewFlag=false;
			for(var j=0; j<rsList[i].code.length ; j++){
				var threeObj=$("div.scr ul li.type"+seName+"_"+rsList[i].code[j]);
				if(threeObj.length>0){
					seViewFlag=true;
				}
				$("div.scr ul li.type"+seName+"_"+rsList[i].code[j]).show();
				if(showList!=null && showList!=""){
					showList+=" ";
				}
				showList+="type"+rsList[i].code[j];
			}
			if(!seViewFlag){
				$("div.scr ul li.type"+seName).hide();
			}
		}
		
	}else{
		$("p.tit").hide();
	}
	if($("p.tit").css("display")=="none"){
		$("p.tit2").show();
	}else{
		$("p.tit2").hide();
	}
	if(!$.fn.isEmptyGis(height)){
		$('.scroll-scrolly_visible').scrollTop(height);
	}
}

functions.showLcstSpace:
$.fn.showLcstSpace = function(){
	if(window.location.pathname == '/web/st/stMapDet.jsp'){
		$.fn.removeStSearch();
	}else{
		$.fn.removeSearch();
	}
	map.addLayer(searchVector);
	var extend = map.getView().calculateExtent(map.getSize());
	var coord = extend[0]+','+ extend[1]+','+extend[2]+','+ extend[3];
	$("div.scr."+pcFlag+" ul li em.on").each(function(){
		if($(this).parent().attr("class")!=null && $(this).parent().attr("class")!=''){
			var codeObj=$(this);
			//var layerNames= $(this).parent().parent().find("li:first").attr("class").replace("ftit","").replace(/(\s*)/g, "").replace("type","");
			var code=$(this).parent().attr("class").replace(/(\s*)/g, "").replace("type","");
			var layerNames = code.split("_")[0];
			code = code.split("_")[1];
			var jsonurl = server+"/MapPlan?req=search";
			var params = {
				version: mapObj["version"],
				layer:layerNames,
				mbr: coord,
				code:code
			};
			$.getJSON(jsonurl,params,function(data, status) {
				if(data != null){
					if(window.location.pathname == '/web/st/stMapDet.jsp'){
						$.fn.showLcstSpaceStPolygon(data, codeObj, code);
						return;
					}
					var features = new ol.format.GeoJSON().readFeatures(data);
					if(features.length > 0){
						searchSource.addFeatures(features);
					}
					map.updateSize();
				}
				
			});
			
		}
	});
}

functions.changeMiniCenter:
$.fn.changeMiniCenter = function(){
	var zoom=miniMap.getView().getZoom();
	var jsonurl = server+"/MapPlan?req=code";
	
	var version=mapObj["version"];
	
	var extend = miniMap.getView().calculateExtent(miniMap.getSize());
	var minx = extend[0];
	var miny = extend[1];
	var maxx = extend[2];
	var maxy = extend[3];
	var coordValue = minx +','+ miny+','+maxx+','+maxy;
	
	var tilesValue="";
	var levelIdValue = zoom-5;
	var accuracyValue =true;
	
	
	var layers=new Array();
	var tile="";
	if(mapObj["miniZoom"]<=15){
		tile=mapObj["tile"];
	}else{
		var type=$.fn.getMapType();
		if(mapObj["version"]!=mapObj["firstVersion"]){
			type=type.replace("N","Y");
		}
		tile=layerObj[type]
	}
	var tileArr = tile.split(",");
	//여기
	var rsList = new Array();
	for(var i=0 ; i<tileArr.length ; i++){
		var params = {
				version: version,
				mbr: coordValue,
				tiles : tileArr[i],
				levelId : levelIdValue,
				accuracy : accuracyValue
		};
		$.getJSON(jsonurl, params, function(data, status) {
			$.each(data, function(i, item) {
				for(var k=0; k<item.length; k++){
					rsList[rsList.length]=item[k];
				}
			});
			$.fn.setLeftMiniHtml(rsList);
		});
	}
}

functions.getSettingMiniMap:
$.fn.getSettingMiniMap = function(){
	mapObj["miniZoom"]=mapObj["zoom"];
	
	var top=$("div.trans_layer").css("top").replace("px","");
	var left=$("div.trans_layer").css("left").replace("px","");
	
	var halfWidth=($("div.trans_layer").width()+6*1)/2;
	var halfHeight=($("div.trans_layer").height()+6*1)/2;
	top=top*1+halfHeight*1;
	left=left*1+halfWidth*1;
	var coord=map.getCoordinateFromPixel([left,top]);
	
	var layers=new Array();
	
	
	var tile="";
	if(mapObj["miniZoom"]<=15){
		tile=mapObj["tile"];
	}else{
		var type=$.fn.getMapType();
		if(mapObj["version"]!=mapObj["firstVersion"]){
			type=type.replace("N","Y");
		}
		tile=layerObj[type]
	}
	
	//var type=$.fn.getMapType();
	//if(mapObj["version"]!=mapObj["firstVersion"]){
	//	type=type.replace("N","Y");
	//}
	//tile=layerObj[type];
	

	var tileArr=tile.split(",");
	
	for(var i=0 ; i<tileArr.length ; i++){
		layers[i] = new ol.layer.Tile({
			source: $.fn.constructSourceEmap(mapObj["version"], tileArr[i])
		});
	}
	
	
	var layersToRemove = [];
	var lays = miniMap.getLayers().getArray();
	for(var i=0; i < lays.length; i++){
		var lay = lays[i];
		layersToRemove.push(lay);
	}
	
	var len = layersToRemove.length;
	for (var i = 0; i < len; i++) {
		miniMap.removeLayer(lay);

	}
	
	for(var i=0 ; i<layers.length ; i++){
		miniMap.addLayer(layers[i]);
	}
	mapObj["miniCenter"]=coord;
	miniMap.getView().setCenter(coord);
	miniMap.getView().animate({
		zoom: mapObj["miniZoom"],
		duration: 0
	});
	miniMap.updateSize();
}

