/**
 * MapPlan 지도 생성
 */
$.fn.constructSourceEmap = function(version, tile) {

	var params = {
		'VERSION': '1.0.0',
		'LAYER': 'emap',
		'STYLE': style,
		'TILEMATRIX': gridNames,
		'TILEMATRIXSET': gridsetName,
		'SERVICE': 'WMTS',
		'FORMAT': format
	};

	function fillzero(n, digits) {
		var zero = '';
		n = n.toString();
		if (digits > n.length) {
			for (var i = 0; digits - n.length > i; i++) {
				zero += '0';
			}
		}
		return zero + n;
	}

	var source = new ol.source.XYZ({
		tileUrlFunction: function (coordinate) {
			if (coordinate == null) {
				return "";
			}
			var z = fillzero(coordinate[0], 2) -5;
			var x = coordinate[1];
			var y = coordinate[2];
			//이미지보정로직
			if(z== "15" && x == "32394" && y== "18155")
			{
				return "https://www.eum.go.kr/web/images/mp/bojung/32394_18155.png";
			}
			else if(z== "14" && x == "16197" && y== "9077")
			{
				return "https://www.eum.go.kr/web/images/mp/bojung/16197_9077.png";
			}
			else
			{
				return server+'/MapPlan?req=timg&timg='+version+'/'+tile+'/' + z  +'/'+ x +'_'+y+'.png'			
			}
			//return server+'/MapPlan?req=timg&timg='+version+'/'+tile+'/' + z  +'/'+ x +'_'+y+'.png'+'&preview=';
			//return "./MapPlan?req=timg&timg="+version+'/'+tile+'/' + z  +'/'+ x +'_'+y+'.png';

		},

		wrapX: true,
		layer: params['LAYER'],
		matrixSet: params['TILEMATRIXSET'],
		format: params['FORMAT'],
		projection: projection,
		tileGrid: new ol.tilegrid.TileGrid({
			tileSize: [256, 256],
			extent: [90000, 1100000, 2180000, 2760000],
			origin: [90000, 1100000.0],
			//extent: [90112, 1192896, 2187264, 2765760],
			//origin: [90112.0, 1192896.0],
			resolutions: resolutions,
			matrixIds: params['TILEMATRIX']
		}),
		crossOrigin: 'anonymous',
		style: params['STYLE']
	});
	return source;
}

