$.fn.getMpLsctCenterLatLng = function(text, code){
	if(!$.fn.isEmptyGis(code)){
		var paramLayerNm=null;
		var paramPnu=null;
		if(code.substring(5,10)=="00000"){
			paramLayerNm="FC";
			paramPnu=code.substring(0,5);
		}else{
			if(code.substring(8,10)=="00"){
				paramLayerNm="FD";
				paramPnu=code.substring(0,8);
			}else{
				paramLayerNm="FE";
				paramPnu=code.substring(0,10);
			}
		}
		
		var jsonurl = server+"/MapPlan?req=search";
		var params = {
				version: mapObj["version"],
				layer:paramLayerNm,
				code: paramPnu
		};
		$.getJSON(jsonurl,params,function(data, status) {
			if(data != null){
				var features = new ol.format.GeoJSON().readFeatures(data);
				var addrSource = new ol.source.Vector();
				addrSource.clear();
				addrSource.addFeatures(features);
				var vectorExtent = addrSource.getExtent();
				var X = vectorExtent[0] + (vectorExtent[2] - vectorExtent[0]) / 2;
				var Y = vectorExtent[1] + (vectorExtent[3] - vectorExtent[1]) / 2;
				var firstProjection = "+proj=tmerc +lat_0=38 +lon_0=127.5 +k=0.9996 +x_0=1000000 +y_0=2000000 +ellps=GRS80 +units=m +no_defs"; //from
				var secondProjection = "+proj=longlat +ellps=WGS84 +datum=WGS84 +no_defs"; //to
				    //I'm not going to redefine those two in latter examples.
				var xy=proj4(firstProjection, secondProjection, [X,Y])
				webMapData("set_lsct_search",text+"_"+code,xy);
			}
		});
	}
}



/**
 * empty 체크 함수
 * 
 * return 여부
 **/
$.fn.isEmptyGis = function(value){ 
	if( value == "" || value == null || value == undefined || value == 'undefined' || ( value != null && typeof value == "object" && !Object.keys(value).length ) ){
		return true 
	}else{ 
		return false 
	} 
};

/**
