	$("div.overPop").hide();
	
	
	$.getJSON(jsonurl,params,function(data, status) {
		if(data.layer != undefined) {
			var htmlStr="";
			for(var i=0 ; i<data.layer.length ; i++){
				var layer=data.layer[i];
				var upCode=layer.name.toUpperCase();
				for(var j=0 ; j<layer.codes.length ; j++){
					var code=layer.codes[j].code;
					var area=layer.codes[j].area;
					area=area.toFixed(1);
					var mainCd=upCode.substr(0, 1);
					if(area>=1.0 && mainCd !="D"){
						area = area.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
						if($("div.scr."+pcFlag+" ul li.type"+upCode+"_"+code).length>0){
							var background=$("div.scr."+pcFlag+" ul li.type"+upCode+"_"+code+" span").css("background");
							var border=$("div.scr."+pcFlag+" ul li.type"+upCode+"_"+code+" span").css("border");
							var text=$("div.scr."+pcFlag+" ul li.type"+upCode+"_"+code).text();
							var span=document.querySelector("div.scr."+pcFlag+" ul li.type"+upCode+"_"+code+" span").outerHTML;
							htmlStr+="<li class='typeOver"+upCode+"_"+code+"' title='"+text+"'>";
							htmlStr+="	<em class=''></em>";
							htmlStr+=span;
							htmlStr+="	<div class='txt'>"+text+"</div>";
							htmlStr+="	<em class='area'>약 "+area+" ㎡</em>";
							htmlStr+="</li>";
						}
					}
				}
			}
			$("div.overPop ul").html(htmlStr);
		}
	
	});
}

