	$(".map_body .subj.pc ul li em.on").each(function(){
		if($(this).hasClass("on") && !$(this).hasClass("disable")){
			var typeStr=$(this).attr("class").replace("disable","").replace("on","").replace( /(\s*)/g, "").replace("type","");
